from pathlib import Path
import sys
from openpyxl import load_workbook
from pptx import Presentation

root = Path(r'C:\Users\win\Desktop\敖钦储能项目')
raw = root / '原始需求'

def cell_text(v):
    if v is None:
        return ''
    s = str(v).replace('\n',' ').strip()
    return ' '.join(s.split())

print('## XLSX SUMMARY')
for path in sorted(raw.rglob('*.xlsx')):
    print(f'FILE: {path.relative_to(root)}')
    try:
        wb = load_workbook(path, read_only=True, data_only=False)
        for ws in wb.worksheets[:12]:
            print(f'  SHEET: {ws.title} rows={ws.max_row} cols={ws.max_column}')
            shown=0
            for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 12), values_only=True):
                vals=[cell_text(v) for v in row]
                vals=[v for v in vals if v]
                if vals:
                    print('    ROW:', ' | '.join(vals[:12]))
                    shown += 1
                if shown>=4:
                    break
        wb.close()
    except Exception as e:
        print(f'  ERROR: {type(e).__name__}: {e}')

print('\n## PPTX SUMMARY')
for path in sorted(raw.rglob('*.pptx')) + sorted(root.glob('*.pptx')):
    print(f'FILE: {path.relative_to(root)}')
    try:
        prs = Presentation(path)
        print(f'  slides={len(prs.slides)}')
        for i, slide in enumerate(prs.slides[:12], 1):
            texts=[]
            for shape in slide.shapes:
                if hasattr(shape, 'text'):
                    t=' '.join(shape.text.split())
                    if t:
                        texts.append(t)
            print(f'  SLIDE {i}: ' + ' || '.join(texts[:6])[:800])
    except Exception as e:
        print(f'  ERROR: {type(e).__name__}: {e}')
