param(
  [int]$Port = 1111,
  [switch]$NoOpen
)

$ErrorActionPreference = 'Stop'

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$ProjectDir = Resolve-Path (Join-Path $ScriptDir '..')
$RepoDir = Resolve-Path (Join-Path $ProjectDir '..')
$Url = "http://127.0.0.1:$Port/"

Set-Location $ProjectDir

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' 敖钦储量及产量规划协同 Demo 一键启动' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host "前端地址: $Url" -ForegroundColor Green
Write-Host '数据来源: 本地 Mock 数据，非真实敖钦/海能/生产系统返回' -ForegroundColor Yellow

$backendDir = Join-Path $RepoDir 'backend'
if (Test-Path -LiteralPath $backendDir) {
  $backendPackage = Join-Path $backendDir 'package.json'
  $backendPom = Join-Path $backendDir 'pom.xml'
  if (Test-Path -LiteralPath $backendPackage) {
    Write-Host '检测到 backend/package.json，将在独立窗口尝试 npm run dev。' -ForegroundColor Yellow
    Start-Process powershell -ArgumentList @(
      '-NoProfile',
      '-ExecutionPolicy', 'Bypass',
      '-NoExit',
      '-Command',
      "Set-Location -LiteralPath '$backendDir'; npm run dev"
    )
  } elseif (Test-Path -LiteralPath $backendPom) {
    Write-Host '检测到 backend/pom.xml；Java 后端启动命令尚未确认，本脚本不擅自启动。' -ForegroundColor Yellow
  } else {
    Write-Host '检测到 backend 目录，但未识别启动方式；本脚本只启动前端。' -ForegroundColor Yellow
  }
} else {
  Write-Host '当前项目没有真实后端目录；本脚本启动前端静态 Demo + Mock 数据。' -ForegroundColor Yellow
}

if (-not (Test-Path -LiteralPath (Join-Path $ProjectDir 'node_modules'))) {
  Write-Host '未检测到 node_modules，正在安装依赖...' -ForegroundColor Yellow
  npm install
}

$portBusy = $false
try {
  $client = New-Object System.Net.Sockets.TcpClient
  $async = $client.BeginConnect('127.0.0.1', $Port, $null, $null)
  $portBusy = $async.AsyncWaitHandle.WaitOne(300, $false)
  if ($portBusy) {
    $client.EndConnect($async)
  }
  $client.Close()
} catch {
  $portBusy = $false
}

if ($portBusy) {
  Write-Host "端口 $Port 已被占用。请关闭占用进程后重试，或运行: .\scripts\start-demo.ps1 -Port 1112" -ForegroundColor Red
  exit 1
}

if (-not $NoOpen) {
  Start-Job -ScriptBlock {
    param($TargetUrl)
    Start-Sleep -Seconds 2
    Start-Process $TargetUrl
  } -ArgumentList $Url | Out-Null
}

Write-Host ''
Write-Host '正在启动 Vite。关闭此窗口或按 Ctrl+C 可停止服务。' -ForegroundColor Green
Write-Host ''

npm run dev -- --host 127.0.0.1 --port $Port --strictPort

